'use strict';
/* Copies tools/dsq_torch_shim.py into public/js/content/m23c_torch_shim.js as one string (TORCH_SHIM), which the PyTorch function sheet runs first.
   Run after editing the .py:   node tools/embed_torch_shim.js   (then node tools/split_content.js if files moved) */
const fs = require('fs'), path = require('path');
const src = fs.readFileSync(path.join(__dirname, 'dsq_torch_shim.py'), 'utf8');
if (/`|\$\{/.test(src)) throw new Error('the shim must not contain a backtick or ${ (it is embedded in a template string)');
const out = `'use strict';
/* GENERATED by tools/embed_torch_shim.js from tools/dsq_torch_shim.py: do not edit by hand.
   A NumPy stand-in for PyTorch (real PyTorch cannot run in a browser). The PyTorch function sheet runs it first, so "import torch" works there. */
const TORCH_SHIM = String.raw\`${src}\`;
`;
fs.writeFileSync(path.join(__dirname, '..', 'public', 'js', 'content', 'm23c_torch_shim.js'), out);
console.log('wrote m23c_torch_shim.js', out.length, 'bytes');
